"""The board: KiCad DRC plus the layout rules from the design that DRC can't express."""
import pcbnew
from conftest import OX, OY, counts, mm

# Accepted, explained in the README: the board is generated by script so KiCad can't match footprints to a
# library table, and KiCad's own GCT USB4105 footprint puts its locating pegs 0.19 mm from the shield pads.
ALLOWED = {"lib_footprint_issues", "hole_clearance"}
HV_BAND = (85.4, 91.0)  # copper-free strip between the HV and LV sides (board mm)
BRIDGES = {"U12", "PS1", "K2", "K3"}  # isolation parts allowed to straddle it


def test_fully_routed(drc):
    assert drc["_unconnected_count"] == 0


def test_only_known_drc_items(drc):
    bad = {k: v for k, v in counts(drc).items() if k not in ALLOWED}
    assert not bad, "\n".join(b[0] for k in bad for b in [drc[k]])


def test_hole_clearance_items_are_only_usb_c(drc):
    for blk in drc.get("hole_clearance", []):
        assert "J5" in blk or "USB" in blk, blk


def _board_xy(p):
    return mm(p.x) - OX, mm(p.y) - OY


def test_no_copper_in_hv_band(board):
    for t in board.GetTracks():
        pts = [t.GetPosition()] if t.Type() == pcbnew.PCB_VIA_T else [t.GetStart(), t.GetEnd()]
        for p in pts:
            x, _ = _board_xy(p)
            assert not HV_BAND[0] < x < HV_BAND[1], f"{t.GetNetname()} copper at x={x:.2f} in the HV band"
    for f in board.GetFootprints():
        if f.GetReference() in BRIDGES:
            continue
        for pad in f.Pads():
            x, _ = _board_xy(pad.GetPosition())
            assert not HV_BAND[0] < x < HV_BAND[1], f"{f.GetReference()} pad in the HV band"


def _slots(board):
    out = []
    for d in board.GetDrawings():
        if d.GetLayer() == pcbnew.Edge_Cuts:
            bb = d.GetBoundingBox()
            x0, y0 = mm(bb.GetLeft()) - OX, mm(bb.GetTop()) - OY
            x1, y1 = mm(bb.GetRight()) - OX, mm(bb.GetBottom()) - OY
            if x0 > 1 and y0 > 1:
                out.append((x0, y0, x1, y1))
    return out


def test_slots_only_under_bridging_parts(board):
    slots = _slots(board)
    assert len(slots) == len(BRIDGES)
    for x0, y0, x1, y1 in slots:
        assert x1 - x0 <= 1.4, "slot wider than needed"
        assert HV_BAND[0] < x0 and x1 < HV_BAND[1]
        under = []
        for ref in BRIDGES:
            bb = board.FindFootprintByReference(ref).GetCourtyard(pcbnew.F_CrtYd).BBox()
            cy0, cy1 = mm(bb.GetTop()) - OY, mm(bb.GetBottom()) - OY
            if cy0 - 0.5 <= y0 and y1 <= cy1 + 0.5:
                under.append(ref)
        assert len(under) == 1, f"slot {y0:.1f}-{y1:.1f} not under exactly one isolation part: {under}"


def test_j3_overhangs_top_edge_wires_outward(board):
    f = board.FindFootprintByReference("J3")
    assert abs(f.GetOrientationDegrees()) == 180
    bb = f.GetCourtyard(pcbnew.F_CrtYd).BBox()
    assert -3.0 < mm(bb.GetTop()) - OY < 0, "J3 body should overhang the top edge slightly"


def test_antenna_keepout(board):
    areas = [z for z in board.Zones() if z.GetIsRuleArea() and z.GetDoNotAllowCopperPour() and z.GetDoNotAllowTracks()]
    assert areas, "ESP32 antenna keep-out missing"


def test_silk_text_min_size(board):
    for f in board.GetFootprints():
        t = f.Reference()
        if t.IsVisible() and t.IsOnLayer(pcbnew.F_SilkS):
            assert mm(t.GetTextSize().y) >= 0.79 and mm(t.GetTextThickness()) >= 0.149, f.GetReference()
